  FT["PH-H7180"] = {"id":"PH-H7180","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1998/ra_8710_1998.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Sigay市","en":"An Act Establishing a National High School in the Municipality of Sigay, Province of Ilocos Sur, to Be Known as the Sigay National High School, and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in the Municipality of Sigay, Province of Ilocos Sur, to Be Known as the Sigay National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8710","issuingBody":"Congress of the Philippines","promulgatedDate":"1998-07-16","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1998/ra_8710_1998.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7180-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the supervision of the Department of Education, Culture and sports a national high school in the Municipality of Sigay, Province of Ilocos Sur, to be known as the Sigay National High School."}},{"id":"PH-H7180-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H7180-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p102"};
  FT["PH-H7181"] = {"id":"PH-H7181","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1998/ra_8711_1998.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将 Sorsogon 省 Pilar 市镇一所中学的附属校分离，改设为独立的 Salvacion 国立中学并为此拨款","en":"An Act Separating the Salvacion High School Annex in the Municipality of Pilar, Province of Sorsogon, From the Pilar Productivity High School, and Converting It Into An Independent National High School to Be Known as the Salvacion National High School and Appropriating Funds Therefor","orig":"An Act Separating the Salvacion High School Annex in the Municipality of Pilar, Province of Sorsogon, From the Pilar Productivity High School, and Converting It Into An Independent National High School to Be Known as the Salvacion National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8711","issuingBody":"Congress of the Philippines","promulgatedDate":"1998-07-16","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1998/ra_8711_1998.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7181-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Salvacion High School Annex in Barangay Salvacion in the Municipality of Pilar, Province of Sorsogon, is hereby separated from the Pilar Productivity High School in the Municipality of Pilar, and converted into an independent national high school to be known as the Salvacion National High School."}},{"id":"PH-H7181-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports (DECS) shall issue rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H7181-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All personnel, assets, liabilities and records of the Salvacion High School Annex are hereby transferred to and absorbed by the Salvacion National High School."}},{"id":"PH-H7181-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Pilar Productivity Development High School-Salvacion Annex. Thereafter, such sums as may be necessary for the operation and maintenance of the Salvacion National High School shall be included in the annual General Appropriations Act,"}},{"id":"PH-H7181-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p102","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Salvacion High School Annex in the Municipality of Pilar, Province of Sorsogon, From the Pilar Productivity High School, and Converting It Into An Independent National High School to Be Known as the Salvacion National High School and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H7182"] = {"id":"PH-H7182","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1998/ra_8712_1998.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Dangcagan市","en":"An Act Establishing a National High School in Poblacion, Municipality of Dangcagan, Province of Bukidnon, to Be Known as the Dangcagan National High School","orig":"An Act Establishing a National High School in Poblacion, Municipality of Dangcagan, Province of Bukidnon, to Be Known as the Dangcagan National High School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8712","issuingBody":"Congress of the Philippines","promulgatedDate":"1998-07-16","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1998/ra_8712_1998.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7182-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established, under the supervision of the Department of Education, Culture and Sports, a national high school in Poblacion, Municipality of Dangcagan, Province of Bukidnon, to be known as the Dangcagan National High School."}},{"id":"PH-H7182-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H7182-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H7182-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p102"};
  FT["PH-H7183"] = {"id":"PH-H7183","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1998/ra_8713_1998.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Sta市","en":"An Act Establishing the Buyabod School of Arts and Trade in the Municipality of Sta. Cruz, Province of Marinduque. and Appropriating Funds Therefor","orig":"An Act Establishing the Buyabod School of Arts and Trade in the Municipality of Sta. Cruz, Province of Marinduque. and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["trade","education","culture"],"docNumber":"Republic Act No. 8713","issuingBody":"Congress of the Philippines","promulgatedDate":"1998-07-16","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1998/ra_8713_1998.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7183-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the supervision of the Technical Education and Skills Development Authority (TESDA) the Buyabod School of Arts and Trade in the Municipality of Sta. Cruz, Province of Marinduque."}},{"id":"PH-H7183-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H7183-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p102"};
  FT["PH-H7184"] = {"id":"PH-H7184","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1998/ra_8714_1998.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将蒙廷卢帕市与拉斯皮纳斯市马尼拉南路萨波特-阿拉邦段更名为费利蒙·C·阿吉拉尔众议员大道，以纪念已故众议员费利蒙·C·阿吉拉尔的法案","en":"An Act Changing the Name of the Manila South-Road, Zapote-Alabang Section in the City of Muntinlupa and City of Las Pinas, Metro Manila, to Congressman Felimon C. Aguilar Avenue in Honor of the Late Congressman Felimon C. Aguilar","orig":"An Act Changing the Name of the Manila South-Road, Zapote-Alabang Section in the City of Muntinlupa and City of Las Pinas, Metro Manila, to Congressman Felimon C. Aguilar Avenue in Honor of the Late Congressman Felimon C. Aguilar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8714","issuingBody":"Congress of the Philippines","promulgatedDate":"1998-07-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1998/ra_8714_1998.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7184-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Hereafter, the Manila South-Road, Zapote-Alabang Section in the City of Muntinlupa and City of Las Pinas, Metro Manila, shall be known as Felimon C. Aguilar Avenue in honor of the late Congressman Felimon C. Aguilar of the Lone District of Las Pinas/Muntinlupa."}},{"id":"PH-H7184-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p102","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Manila South-Road, Zapote-Alabang Section in the City of Muntinlupa and City of Las Pinas, Metro Manila, to Congressman Felimon C. Aguilar Avenue in Honor of the Late Congressman Felimon C. Aguilar","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H7185"] = {"id":"PH-H7185","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1998/ra_8715_1998.html","fetchedAt":"2026-10-06","articleCount":20,"structureMode":"ARTICLE","title":{"zh":"授予 Tandag 电力电话公司在南苏里高省建设、设立、安装、维护和运营本地交换网络的特许经营权法案","en":"An Act Granting the Tandag Electric and Telephone Company, Inc., a Franchise to Construct, Establish, Install, Maintain and Operate Local Exchange Network in the Province of Surigao Del Sur","orig":"An Act Granting the Tandag Electric and Telephone Company, Inc., a Franchise to Construct, Establish, Install, Maintain and Operate Local Exchange Network in the Province of Surigao Del Sur"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 8715","issuingBody":"Congress of the Philippines","promulgatedDate":"1998-07-16","completenessNote":"全文，共 20 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1998/ra_8715_1998.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7185-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Tandag Electric and Telephone Company, Inc., hereunder referred to as the grantee, its successors or assigns, a franchise to construct, establish, install, maintain and operate for commercial purposes and in the public interest, local exchange network, including public calling stations or pay telephone stations or wireless local loop and for such purpose provide basic telephone service or other means related to the foregoing now known to science or which in the future may be developed in the Province of Surigao del Sur, for public domestic telecommunications."}},{"id":"PH-H7185-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof. In no way shall the operations of the grantee, nor the radiated power of its stations or facilities, exceed that required cover the area where it is allowed to operate."}},{"id":"PH-H7185-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Authority of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunication Commission, hereinafter referred to as the Commission, a certificate of public convenience and necessity or the appropriate permits and licenses for the location, construction, installation and operation of its telecommunications systems. In issuing the certificate, the Commission shall have the power to impose such conditions relative the construction, operation, maintenance, of service level of the telecommunication systems. The Commission shall have the authority to regulate the construction and operation of its telecommunications systems. The grantee shall not use any frequency in the radio spectrum without having been authorized by the Commission. Such certificate shall state the areas covered and date the grantee shall commence the service. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority, permits or licenses."}},{"id":"PH-H7185-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall conform to the ethics of honest enterprise and shall not use its stations for obscene or indecent transmission or for dissemination of deliberately false information or willful misrepresentation, or assist in subversive or treasonable acts.\nThe grantee shall provide basic enhanced telephone service within the Province of Surigao del Sur, where it has an approved certificate of public convenience and necessity for the establishment, operation and maintenance of a local exchange service, without discrimination to any applicant therefor, in the order of the date of their applications, up to the limit of the capacity of its local telephone exchange service, and should the demand for the telephone service at any time increase beyond the capacity thereof, the grantee shall increase the same to meet such demand: Provided, That in case the total demand to be satisfied by the expansion is less than the smallest viable local exchange available in the market as determined by the Commission, the grantee shall not be obliged to furnish said service, unless the applicant for telephone service defrays the actual expenses for the installation of the telecommunication apparatus necessary for such services and in such case, the Commission may extend the time within which the grantee shall furnish such service.\nThe grantee shall operate and maintain all its stations, lines, cables, systems, and equipment for the transmission and reception of messages, signals and pulses in a satisfactory manner at all times, and as far as economical and practicable, modify, improve or change such stations, lines, cables, systems, and equipment to keep abreast with the advances in science and technology."}},{"id":"PH-H7185-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Rates for Services. - The charges and rates for telecommunications services of the grantee, except the rates and charges on those that may hereafter be declared or considered as non-regulated services, whether flat rates or measured rates or variation thereof, shall be subject to the approval of the Commission or its legal successors. The rates to be charged by the grantee shall be unbundled, separable and distinct among the services offered and shall be determined in such a manner that regulated services do not subsidize the unregulated ones."}},{"id":"PH-H7185-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Right of Government. - A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations, transmitters, facilities or equipment of the grantee. to temporarily suspend the operation of any station, transmitter, facility or equipment in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee for the use of said stations, transmitters, facilities or equipment during the period when they shall be so operated.\nThe radio spectrum is a finite resource that is a part of the national patrimony and the use thereof is a privilege conferred upon the grantee by the State and may be withdrawn anytime, after due process."}},{"id":"PH-H7185-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked in the event the grantee fails to comply with any of the following conditions:\na. Commence operations within three (3) years from the approval of its permit or provisional authority by the National Telecommunications Commission;\nb. Operate continuously for two (2) years; and\nc. Commence operations within five (5) years from the effectivity of this Act."}},{"id":"PH-H7185-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing within sixty (60) days from the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Non-acceptance shall render the franchise void."}},{"id":"PH-H7185-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Bond. - The grantee shall file a bond issued in favor of the National Telecommunications Commission, which shall determine the amount, to guarantee the compliance with and fulfillment of the conditions under which this franchise is granted. If after five (5) years from the date of the approval of its permit by the Commission, the grantee shall have fulfilled the same, the bond shall be canceled by the Commission. Otherwise the bond shall be forfeited in favor of the government and the franchise ipso facto revoked."}},{"id":"PH-H7185-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Right of Interconnection. - The grantee is hereby authorized to connect or demand connection of its telecommunications systems to any other telecommunications systems installed, operated and maintained by any other duly authorized person or entity in the Philippines for the purpose of providing extended and improved telecommunications services to the public under such terms and conditions mutually agreed upon by the parties concerned and the same shall be subject to the review or modification of the Commission."}},{"id":"PH-H7185-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns, shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay the value-added tax under Republic Act No. 7716, as amended, or a franchise tax of three (3%) per annum or at such percentage as may be prescribed by law, on all gross receipts of its telecommunications business transacted under this franchise, whichever is higher Provided, That the grantee, its successors or assigns, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72, unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with, and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representatives in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H7185-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Gross Receipts. - The grantee, its successors or assigns, shall keep a separate account of the gross receipts of the business transacted by it and shall furnish the Commission on Audit and the National Treasury a copy of such account not later than the 31st day of January of each year for the preceding twelve (12) months."}},{"id":"PH-H7185-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Books and Accounts. - The books and accounts of the grantee, its successors or assigns, shall always be open to the inspection of the Commissioner on Audit or his authorized representatives, and it shall be the duty of the grantee to submit to the Commission on Audit, two (2) copies of the quarterly reports on the gross receipts, the net profits and the general condition of the business."}},{"id":"PH-H7185-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations, transmitters, facilities and equipment of the grantee."}},{"id":"PH-H7185-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Sale, Lease, Transfer, Usufruct Etc. - The grantee shall not lease, transfer grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired there under to any person, firm, company corporation or other commercial or legal entity, nor merge with any corporation or entity, nor shall the controlling interest of the grantee be transferred, whether as a whole or in parts and whether simultaneous or contemporaneously, to any such person firm, company corporation or entity without the prior approval of the Congress of the Philippines, except when such person, firm, company, corporation or entity has a valid and existing legislative franchise for telecommunications or it is in pursuance of provision of Section 16 of this Act. Any person or entity to which this franchise is sold, transferred or assigned, shall be subject to the same conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H7185-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Dispersal of Ownership. - In accordance with the constitutional provisions to encourage public participation in the public utilities, the grantee shall offer at least thirty per centum (30%) of its outstanding capital stock or a higher percentage that may hereafter be provided by law in any securities exchange in the Philippines within ten (10) years from the commencement of its operations. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H7185-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Separability Clause. - If any of the section or provisions of this Act is held invalid, all other provisions not affected thereby shall remain valid."}},{"id":"PH-H7185-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Repealability and Non-exclusivity. - This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H7185-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of its franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H7185-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p102","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Tandag Electric and Telephone Company, Inc., a Franchise to Construct, Establish, Install, Maintain and Operate Local Exchange Network in the Province of Surigao Del Sur","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H7186"] = {"id":"PH-H7186","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1998/ra_8716_1998.html","fetchedAt":"2026-10-06","articleCount":20,"structureMode":"ARTICLE","title":{"zh":"授予 North Camarines 电话公司在北甘马粦省 Daet 市镇建设、设立、安装、维护和运营本地交换网络的特许经营权法案","en":"An Act Granting the North Camarines Telephone Co., Inc. a Franchise to Construct, Establish, Install, Maintain and Operate Local Exchange Network in the Municipality of Daet, Province of Camarines Norte","orig":"An Act Granting the North Camarines Telephone Co., Inc. a Franchise to Construct, Establish, Install, Maintain and Operate Local Exchange Network in the Municipality of Daet, Province of Camarines Norte"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 8716","issuingBody":"Congress of the Philippines","promulgatedDate":"1998-07-16","completenessNote":"全文，共 20 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1998/ra_8716_1998.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7186-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. — Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the North Camarines Telephone Co., Inc., hereunder referred to as the grantee, its successors or assigns, a franchise to construct, establish, install, maintain and operate for commercial purposes and in the public interest, including local exchange network, including public calling stations or pay telephone stations or wireless local loop and for such purpose provide basic telephone service or other means related to the foregoing now known to science or which in the future may be developed in the Municipality of Daet, Province of Camarines Norte, for public domestic telecommunications."}},{"id":"PH-H7186-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. — The stations or facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of the existing stations or other stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof. In no way shall the operations of the grantee, nor the radiated power of its stations or facilities, exceed that required to cover the area where it is allowed to operate."}},{"id":"PH-H7186-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Authority of the National Telecommunications Commission. — The grantee shall secure from the National Telecommunications Commission, hereinafter referred to as the Commission, a certificate of public convenience and necessity or the appropriate permits and licenses for the location, construction, installation and operation of its telecommunications systems. In issuing the certificate, the Commission shall have the power to impose such conditions relative to the construction, operation, maintenance, or service level of the telecommunications systems. The Commission shall have the authority to regulate the construction and operation of its telecommunications systems. The grantee shall not use any frequency in the radio spectrum without having been authorized by the Commission. Such certificate shall state the areas covered and date the grantee shall commence the service. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority, permits or licenses."}},{"id":"PH-H7186-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. — The grantee shall conform to the ethics of honest enterprise and shall not use its stations for obscene or indecent transmission or for dissemination of deliberately false information or willful misrepresentation, or assist in subversive or treasonable acts.\nThe grantee shall provide basic or enhanced telephone service within the Municipality of Daet, Province of Camarines Norte, where it has an approved certificate of public convenience and necessity for the establishment, operation and maintenance of a local exchange service, without discrimination to any applicant therefor, in the order of the date of their applications, up to the limit of the capacity of its local telephone exchange, and should the demand for the telephone service at any time increase beyond the capacity thereof, the grantee shall increase the same to meet such demand: Provided, That, in case the total demand to be satisfied by the expansion is less than the smallest viable local exchange available in the market as determined by the Commission, the grantee shall not be obliged to furnish said service, unless the applicant for telephone service defrays the actual expenses for the installation of the telecommunication apparatus necessary for such services and in such case, the Commission may extend the time within which the grantee shall furnish such service.\nThe grantee shall operate and maintain all its stations, lines, cables, systems, and equipment for the transmission and reception of messages, signals and pulses in a satisfactory manner at all times, and as far as economical and practicable, modify, improve or change such stations, lines, cables, systems, and equipment to keep abreast with the advances in science and technology."}},{"id":"PH-H7186-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Rates for Services. — The charges and rates for telecommunications services of the grantee, except the rates and charges on those that may hereafter be declared or considered as nonregulated services, whether flat rates or measured rates or variation thereof, shall be subject to the approval of the Commission or its legal successors. The rates to be charged by the grantee shall be unbundled, separable and distinct among the services offered and shall be determined in such a manner that regulated services do not subsidize the unregulated ones."}},{"id":"PH-H7186-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Right of Government. — A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations, transmitters, facilities or equipment of the grantee, to temporarily suspend the operation of any station, transmitter, facility or equipment in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee for the use of said stations, transmitters, facilities or equipment during the period when they shall be so operated.\nThe radio spectrum is a finite resource that is a part of the national patrimony and the use thereof is a privilege conferred upon the grantee by the State and may be withdrawn anytime, after due process."}},{"id":"PH-H7186-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Term of Franchise. — This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked, in the event the grantee fails to comply with any of the following conditions:\na. Commence operations within three (3) years from the approval of its operating permit or provisional authority by the National Telecommunications Commission;\nb. Operate continuously for two (2) years; and\nc. Commence operations within five (5) years from the effectivity of this Act."}},{"id":"PH-H7186-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Acceptance and Compliance. — Acceptance of this franchise shall be given in writing within sixty (60) days from the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H7186-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Bond. — The grantee shall file a bond issued in favor of the National Telecommunications Commission, which shall determine the amount, to guarantee the compliance with and fulfillment of the conditions under which this franchise is granted. If after five (5) years from the date of the approval of its permit by the Commission, the grantee shall have fulfilled the same, the bond shall be cancelled by the Commission. Otherwise, the bond shall be forfeited in favor of the government and the franchise ipso facto revoked."}},{"id":"PH-H7186-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Right of Interconnection. — The grantee is hereby authorized to connect or demand connection of its telecommunications systems to any other telecommunications systems installed, operated and maintained by any other duly authorized person or entity in the Philippines for the purpose of providing extended and improved telecommunications services to the public under such terms and conditions mutually agreed upon by the parties concerned and the same shall be subject to the review or modification of the Commission."}},{"id":"PH-H7186-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Tax Provisions. — The grantee, its successors or assigns, shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns, shall pay the value-added tax under Republic Act No. 7716, as amended, or a franchise tax of three percent (3%) per annum or at such percentage as may be prescribed by law, on all gross receipts of its telecommunications business transacted under this franchise, whichever is higher: Provided, That the grantee, its successors or assigns, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72, unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with, and pay the taxes due thereon to the Commissioner of Internal Revenue or his duly authorized representatives in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H7186-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Gross Receipts. — The grantee, its successors or assigns, shall keep a separate account of the gross receipts of the business transacted by it and shall furnish the Commission on Audit and the National Treasury a copy of such account not later than the 31st day of January of each year for the preceding twelve (12) months."}},{"id":"PH-H7186-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Books and Accounts. — The books and accounts of the grantee, its successors or assigns, shall always be open to the inspection of the Commissioner on Audit or his authorized representatives, and it shall be the duty of the grantee to submit to the Commission on Audit, two (2) copies of the quarterly reports on the gross receipts, the net profits and the general condition of the business."}},{"id":"PH-H7186-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Warranty in Favor of National and Local Governments. — The grantee shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations, transmitters, facilities and equipment of the grantee."}},{"id":"PH-H7186-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. — The grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any corporation or entity, nor shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines, except when such person, firm, company, corporation or entity has a valid and existing legislative franchise for telecommunications or it is in pursuance of the provision of Section 16 of this Act. Any person or entity to which this franchise is sold, transferred or assigned, shall be subject to the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H7186-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Dispersal of Ownership. — In accordance with the constitutional provisions to encourage public participation in the public utilities, the grantee shall offer at least thirty per centum (30%) of its outstanding capital stock or a higher percentage that may hereafter be provided by law in any securities exchange in the Philippines within ten (10) years from the commencement of its operations. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H7186-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Separability Clause. — If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H7186-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Repealability and Nonexclusivity Clause. — This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H7186-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Reportorial Requirement. — The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of its franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H7186-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Effectivity. — This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p102","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the North Camarines Telephone Co., Inc. a Franchise to Construct, Establish, Install, Maintain and Operate Local Exchange Network in the Municipality of Daet, Province of Camarines Norte","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H7187"] = {"id":"PH-H7187","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1998/ra_8717_1998.html","fetchedAt":"2026-10-06","articleCount":18,"structureMode":"ARTICLE","title":{"zh":"授予 E.M. Orosco and Sons，Inc. 在菲律宾建设、安装、设立、运营和维护广播与电视站的特许经营权法案","en":"An Act Granting the E.M. Orosco &amp; Sons, Inc., a Franchise to Construct, Install, Establish, Operate and Maintain Radio and Television Stations in the Philippines","orig":"An Act Granting the E.M. Orosco &amp; Sons, Inc., a Franchise to Construct, Install, Establish, Operate and Maintain Radio and Television Stations in the Philippines"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 8717","issuingBody":"Congress of the Philippines","promulgatedDate":"1998-07-16","completenessNote":"全文，共 18 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1998/ra_8717_1998.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7187-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the E.M. Orosco & Sons, Inc., hereunder referred to as the grantee, its successors or assigns, a franchise to construct, install, establish, operate and maintain for commercial purposes and in the public interest, radio and/or television broadcasting stations in the Philippines, where frequencies and/or channels are still available for radio and/or television broadcasting, with the corresponding technological auxiliaries or facilities, special broadcast and other program and distribution services and relay stations."}},{"id":"PH-H7187-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H7187-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for the construction and operation of its stations and facilities and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H7187-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall provide adequate public service time to enable the government, through the said broadcasting stations or facilities, to reach the population on important public issues; provide at all times sound and balanced programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations or facilities for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, to the detriment of the public interest, or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H7187-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. - A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations or facilities of the grantee, to temporarily suspend the operation of any station or facility in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said stations or facilities during the period when they shall be so operated.\nThe radio spectrum is a finite resource that is a part of the national patrimony and the use thereof is a privilege conferred upon the grantee by, the State and may be withdrawn anytime, after due process."}},{"id":"PH-H7187-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked in the event the grantee fails to comply with any of the following conditions:\na. Commence operations within one (1) year from the approval of its permit by the National Telecommunications Commission;\nb. Operate continuously for two (2) years; and\nc. Commence operations within three (3) years from the effectivity of this Act."}},{"id":"PH-H7187-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing within sixty (60) days from the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Non-acceptance shall render the franchise void."}},{"id":"PH-H7187-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Bond. - The grantee shall file a bond issued in favor of the National Telecommunications Commission, which shall determine the amount, to guarantee the compliance with and fulfillment of the conditions under which this franchise is granted. If after three (3) years from the date of the approval of its permit by the Commission, the grantee shall have fulfilled the same, the bond shall be cancelled by the Commission. Otherwise, the bond shall be forfeited in favor of the governï¿½ment and the franchise ipso facto revoked."}},{"id":"PH-H7187-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns, shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns, shall pay the value-added tax under Republic Act No. 7716, as amended, on all gross receipts of its radio/ television business transacted under this franchise: Provided, That the grantee, its successors or assigns, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72, unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the taxes due thereon to the Commissioner of Internal Revenue or his duly authorized representatives in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H7187-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Self-regulation by and Undertaking of Grantee. - The grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast from its stations: Provided, That the grantee, during any broadcast, shall cut off from the air speech, play, act or scene, or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral; and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H7187-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial, and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H7187-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired there under to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other corporation or entity, nor shall the controlling interest of the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned, shall be subject to the same conditions, terms restrictions and limitations of this Act."}},{"id":"PH-H7187-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Dispersal of Ownership. - In accordance with constitutional provisions to encourage public participation in public utilities, the grantee shall offer at least thirty percentum (30%) of its outstanding capital stock or a higher percentage that may hereafter be provided by law in any securities exchange in the Philippines within five (5) years from the time it has achieved the status of a national broadcasting network. A \"national broadcasting network\" is hereby defined as one that operates three or more radio and/or television stations. Non-compliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H7187-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"General Broadcast Policy Law. - The grantee shall comply with and be subject to the provisions of a general broadcast policy law which Congress may hereafter enact."}},{"id":"PH-H7187-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Separability Clause. - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H7187-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Repealability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H7187-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H7187-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Effectivity. ï¿½This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p102","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the E.M. Orosco &amp; Sons, Inc., a Franchise to Construct, Install, Establish, Operate and Maintain Radio and Television Stations in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
